import openpyxl,re
wb=openpyxl.load_workbook('extraction/mac-gray.xlsx')
ws=wb['Deal ledger']
flags={}
for r in ws.iter_rows(min_row=2,values_only=True):
    flags[r[0]]=[x.strip() for x in (r[17] or '').split(';') if x.strip()]

def expand(s):
    out=[]
    for part in str(s).split(','):
        part=part.strip()
        if '-' in part:
            a,b=part.split('-'); out+=list(range(int(a),int(b)+1))
        else: out.append(int(part))
    return out

q=wb['Questions']
bad=0
for r in q.iter_rows(min_row=2,values_only=True):
    qid=r[0]
    for n in expand(r[4]):
        if qid not in flags.get(n,[]):
            print('MISMATCH',qid,n); bad+=1
print('mismatches:',bad)
# reverse check: flagged rows not cited
cited={}
for r in q.iter_rows(min_row=2,values_only=True):
    for n in expand(r[4]): cited.setdefault(n,set()).add(r[0])
for n,fl in flags.items():
    for f in fl:
        if f not in cited.get(n,set()): print('EXTRA FLAG',n,f)
print('rows flagged:',sum(1 for v in flags.values() if v),'of',len(flags))

acct=[r[1].value for r in wb['Deal facts'].iter_rows(min_row=2) if r[0].value=='Account'][0]
sents=re.split(r'(?<!\$\d)(?<!\d)\.\s+',acct)
sents=[s for s in re.split(r'\.\s+(?=[A-Z])',acct) if s.strip()]
print('\nsentences:',len(sents))
for s in sents: print(' *',s[:80])
